# Twin of t213: every group of order 3875 = 5^3 * 31 has a normal Sylow p-subgroup (p prime, p | 3875).
# Enumerate all Sylow-admissible (n_p) with every n_p > 1 and show each is impossible by element counting:
#  - exponent-1 prime p: n_p*(p-1) elements of order p;
#  - exponent-a prime p (a >= 2), n_p >= 2: at least 2*p^a - p^(a-1) - 1 nonidentity p-elements.
from itertools import product
def factor(n):
    f, d = {}, 2
    while d * d <= n:
        while n % d == 0:
            f[d] = f.get(d, 0) + 1
            n //= d
        d += 1
    if n > 1:
        f[n] = f.get(n, 0) + 1
    return f
N = 3875
f = factor(N)
allowed = {p: [d for d in range(1, N // p**a + 1) if (N // p**a) % d == 0 and d % p == 1] for p, a in f.items()}
print(f, allowed)
ok = True
ps = list(f)
for combo in product(*[[x for x in allowed[p] if x > 1] for p in ps]):
    count = 1
    for p, n in zip(ps, combo):
        a = f[p]
        count += n * (p - 1) if a == 1 else 2 * p**a - p**(a - 1) - 1
    print(dict(zip(ps, combo)), "lower bound on |G|:", count)
    if count <= N:
        ok = False
print(ok)
